import{_ as a,o as e,c as r,a3 as d}from"./chunks/framework.Dj4Lt7vj.js";const p=JSON.parse('{"title":"方案编辑器","description":"","frontmatter":{"title":"方案编辑器"},"headers":[],"relativePath":"solution/editor.md","filePath":"solution/editor.md","lastUpdated":1787948622000}'),o={name:"solution/editor.md"};function i(l,t,s,n,h,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="方案编辑器" tabindex="-1">方案编辑器 <a class="header-anchor" href="#方案编辑器" aria-label="Permalink to &quot;方案编辑器&quot;">​</a></h1><p>AI 方案决定 AI 怎么回复。这一页讲怎么创建方案、编辑器里有哪些模块、以及怎么把方案挂到店铺上。</p><h2 id="创建方案" tabindex="-1">创建方案 <a class="header-anchor" href="#创建方案" aria-label="Permalink to &quot;创建方案&quot;">​</a></h2><ol><li>打开客户端左侧菜单「店铺方案」。</li><li>点「新建方案」，起一个能看出用途的名字，比如「女装主店」「售后专用」。</li><li>创建后进入方案编辑首页。</li></ol><p>一个方案可以给多个店铺用。同类目的店铺共用一个方案最省事；话术差异大的店铺再拆开建。</p><h2 id="编辑器首页的八个模块" tabindex="-1">编辑器首页的八个模块 <a class="header-anchor" href="#编辑器首页的八个模块" aria-label="Permalink to &quot;编辑器首页的八个模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>作用</th><th>详细文档</th></tr></thead><tbody><tr><td>AI 设置</td><td>角色设定、智能程度、可用工具、情景配置</td><td><a href="/aicare-docs/solution/agents">AI 设置与智能程度</a></td></tr><tr><td>知识库</td><td>绑定这个方案要参考的知识库</td><td><a href="/aicare-docs/knowledge/basics">知识库是什么</a></td></tr><tr><td>表格</td><td>绑定查询表和登记表</td><td><a href="/aicare-docs/solution/tables">查询表与登记表</a></td></tr><tr><td>特殊消息处理</td><td>订单、图片、链接等特殊消息按类型设置预设回复或 AI 识别方式</td><td>见下文</td></tr><tr><td>关键词设置</td><td>命中关键词时用固定话术，优先级高于 AI</td><td><a href="/aicare-docs/solution/keywords">关键词回复</a></td></tr><tr><td>通用配置</td><td>消息间隔、夜间模式、新客欢迎语、兜底回复等</td><td><a href="/aicare-docs/solution/general">通用配置</a></td></tr><tr><td>催付设置</td><td>按任务配置催付时机、商品范围和话术</td><td>见下文</td></tr><tr><td>对话测试</td><td>上线前模拟顾客提问，检查回复效果</td><td><a href="/aicare-docs/solution/test">对话测试</a></td></tr></tbody></table><h3 id="特殊消息处理" tabindex="-1">特殊消息处理 <a class="header-anchor" href="#特殊消息处理" aria-label="Permalink to &quot;特殊消息处理&quot;">​</a></h3><p>顾客发来的不是文字时——订单卡片、图片、商品链接——可以按消息类型单独设置处理方式：用预设回复直接答，或交给 AI 识别内容后再回。不设置时走默认处理。</p><h3 id="催付设置" tabindex="-1">催付设置 <a class="header-anchor" href="#催付设置" aria-label="Permalink to &quot;催付设置&quot;">​</a></h3><p>催付功能有总开关。开启后，AI 按你配置的催付任务，在合适的时机主动提醒顾客付款。每个任务对应一个催付场景，可以设置触发条件、商品范围、话术和优先级，并单独启用或停用。</p><h2 id="把方案挂到店铺上" tabindex="-1">把方案挂到店铺上 <a class="header-anchor" href="#把方案挂到店铺上" aria-label="Permalink to &quot;把方案挂到店铺上&quot;">​</a></h2><p>方案建好后要绑定到店铺才生效：</p><ol><li>回到「店铺客服」，点击店铺卡片进入店铺设置。</li><li>在「AI 方案」一栏选择刚建的方案。</li><li>保存。该店铺下所有开着 AI 接待的客服账号立即按新方案回复。</li></ol><h2 id="推荐的配置顺序" tabindex="-1">推荐的配置顺序 <a class="header-anchor" href="#推荐的配置顺序" aria-label="Permalink to &quot;推荐的配置顺序&quot;">​</a></h2><p>第一次配置方案，按这个顺序走最顺：</p><ol><li><strong>AI 设置</strong>：写清楚店铺卖什么、AI 该用什么语气。</li><li><strong>知识库</strong>：绑定售后政策、发货说明等资料。</li><li><strong>通用配置</strong>：设置新客欢迎语和夜间模式。</li><li><strong>关键词设置</strong>：把活动话术等固定答案配上。</li><li><strong>对话测试</strong>：拿真实顾客的问法测一轮，不满意回头调。</li><li>绑定店铺，开启 AI 接待。</li></ol>',17)])])}const b=a(o,[["render",i]]);export{p as __pageData,b as default};
